CREATE TABLE "ScannerBatch" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"provider" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'IMPORTED',"totalCount" INTEGER NOT NULL DEFAULT 0,"analyzedCount" INTEGER NOT NULL DEFAULT 0,"failedCount" INTEGER NOT NULL DEFAULT 0,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "ScannerBatch_userId_fkey" FOREIGN KEY("userId") REFERENCES "UserProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "ScannerBatch_userId_createdAt_idx" ON "ScannerBatch"("userId","createdAt");
CREATE TABLE "ScannerListing" ("id" TEXT NOT NULL PRIMARY KEY,"scannerBatchId" TEXT NOT NULL,"auctionListingId" TEXT,"rowNumber" INTEGER NOT NULL,"sourceTitle" TEXT NOT NULL,"sourceUrl" TEXT,"sourceMarketplace" TEXT NOT NULL,"rawPayload" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"errorMessage" TEXT,"marketRankScore" INTEGER,"analyzedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "ScannerListing_scannerBatchId_fkey" FOREIGN KEY("scannerBatchId") REFERENCES "ScannerBatch"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "ScannerListing_auctionListingId_fkey" FOREIGN KEY("auctionListingId") REFERENCES "AuctionListing"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "ScannerListing_auctionListingId_key" ON "ScannerListing"("auctionListingId"); CREATE UNIQUE INDEX "ScannerListing_scannerBatchId_rowNumber_key" ON "ScannerListing"("scannerBatchId","rowNumber"); CREATE INDEX "ScannerListing_scannerBatchId_status_marketRankScore_idx" ON "ScannerListing"("scannerBatchId","status","marketRankScore");
